        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Physical activity in daily life",
              "description": "The totality of voluntary movement produced by skeletal muscles during everyday functioning will be assess by an activity monitor (ActiGraph) which will provide data of number of steps per day, and time spent in postures and activities of different intensities.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Patient's perception of physical activity in daily life",
              "description": "The questionnaire PROactive Physical Activity in COPD, that measures the patients' percpetion of physical activities performed in daily living, will be used to complement the evaluation of physical activity level. It is composed by 12 items that evaluate difficulty in performing activities in daily life. Each item scores from 0 to 4; the total score is provided by summing all items and higher scores indicate higher physical activity level.",
              "timeFrame": "24 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Dyspnoea sensation in daily living",
              "description": "The Medical Research Council (MRC) scale will be used to assess limitation in activities of daily living due to dyspnoea sensation. The scale varies from 1 to 5 points; higher scores indicate higher limitation due to dyspnoea.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Acute exacerbation",
              "description": "Acute exacerbations are episodes of acute worsening of the respiratory symptoms of patients with chronic lung disease, that result in additional therapy. Occurrence of those episodes during the research protocol will be self-reported in the visits.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Hospitalization",
              "description": "Hospital admission due to respiratory conditions. Occurrence of this event during the research protocol will be self-reported in the visits.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Functional status",
              "description": "Functional status is an individual's ability to perform normal daily activities required to meet basic needs, fulfill usual roles, and maintain health and well-being. The London Chest Activity of Daily Living (LCADL) scale, a validated tool to assess patients with chronic pulmonary disease, will be used to assess functional limitation. The scale is composed by 15 items divided in 4 domains; each item is scored from 0 to 5 points, indicating to what extent dyspnoea sensation limits functionality. The total score is calculated by summing all items; higher scores indicate worse functional status.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Health-related Quality of life",
              "description": "Quality of life is a term used to refer to an individual's total well-being. An specific questionnaire, the Brazilian version of the Modified Saint George´s Respiratory Questionnaire (mSGRQ), will be used to assess those patients with COPD and asthma. It is composed by 50 items that evaluate limitation of quality of life due to respiratory symptoms; they are divided in 3 domains: symptoms, activity and impact. Patients' responses are \"agree\" or \"do not agree\". The total score is calculated by summing the 3 domains; higher scores indicate worse quality of life.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Health-related Quality of life",
              "description": "Quality of life is a term used to refer to an individual's total well-being. An specific questionnaire, the Brazilian version of the Saint George´s Respiratory Questionnaire specifically developed for idiopathic pulmonary fibrosis patients (SGRQ-I), will be used to assess those patients with interstitial lung diseases. It is composed by 34 items that evaluate limitation of quality of life due to respiratory symptoms; they are divided in 3 domains: symptoms, activity and impact. The total score is calculated by summing the 3 domains varing from 0 to 100; higher scores indicate more impaired quality of life.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Sleep quality",
              "description": "Sleep quality is defined as one's satisfaction of the sleep experience, integrating aspects of sleep initiation, sleep maintenance, sleep quantity, and refreshment upon awakening. The Pittsburgh Sleep Quality Index (PSQI) will be used to asssess sleep quality. It is composed by 19 item grouped into 7 components: sleep duration, sleep disturbance, sleep latency, daytime dysfunction due to sleepiness, sleep efficiency, overall sleep quality, sleep medication use. Each of the sleep components yields a score ranging from 0 to 3; the total score is provided by summing all components, ranging from 0 to 21 points with the higher total score indicating worse sleep quality.",
              "timeFrame": "24 months"
            },
            {
              "measure": "Anxiety and depression",
              "description": "Presence of symptoms of anxiety and depression that the patients are experiencing will be assess by the Hospital Anxiety and Depression Scale (HADS). It is a 14-item scale with 7 items each for anxiety and depression subscales. Scoring for each item ranges from 0 to 3. A subscale score \\> 8 indicates anxiety or depression.",
              "timeFrame": "24 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Diagnosis of chronic obstructive pulmonary disease, asthma or interstitial lung disease;\n* Absence of any severe and/or unstable cardiac disease;\n* Absence of any orthopedic or neuromuscular condition that limits physical activity in daily life.\n\nExclusion Criteria:\n\n* Desire to leave the study at any time;\n* Infection with SARS-CoV-2 during the study protocol.",
